using System.Collections.Generic;public class Solution{Dictionary<string,List<(string,double)>>g=new();double F(string u,string t,HashSet<string>v){if(!g.ContainsKey(u))return-1;if(u==t)return 1;v.Add(u);foreach(var e in g[u])if(!v.Contains(e.Item1)){double r=F(e.Item1,t,v);if(r>0)return e.Item2*r;}return-1;}public double[] CalcEquation(IList<IList<string>>e,double[]val,IList<IList<string>>q){for(int i=0;i<e.Count;i++){string a=e[i][0],b=e[i][1];if(!g.ContainsKey(a))g[a]=new();if(!g.ContainsKey(b))g[b]=new();g[a].Add((b,val[i]));g[b].Add((a,1.0/val[i]));}double[]o=new double[q.Count];for(int i=0;i<q.Count;i++)o[i]=F(q[i][0],q[i][1],new HashSet<string>());return o;}}
